/// Real Java 11 members caturra cannot model, per class, with the honest
/// reason — students find these in documentation, and "cannot find
/// symbol" would read as a bug.
#[rustfmt::skip]
const UNSUPPORTED_MEMBERS: &[(&str, &str, &str)] = &[
    // A class's access flags are not modelled, and could not be answered
    // honestly if they were: a LIBRARY class has no class file here, and a
    // nested one is flattened to the top level, so the `static` and `private`
    // bits a JDK reports from the InnerClasses attribute are gone. A number
    // that is right for a top-level user class and quietly wrong for the other
    // two is worse than saying so. (`Field`/`Method`/`Constructor`
    // `getModifiers` ARE answered — those flags survive.)
    ("Class", "getModifiers", "caturra does not model a class's access flags"),
    ("Class", "getPackage", "caturra does not model java.lang.Package"),
    ("Integer", "getInteger", "system properties are not supported by caturra"),
    ("ArrayList", "parallelStream", "caturra runs on one thread, so a parallel stream would only be a sequential one under another name"),
    ("Scanner", "findInLine", "caturra's Scanner reads whole tokens and cannot search within a line"),
    ("Scanner", "findWithinHorizon", "caturra's Scanner reads whole tokens and cannot search within a horizon"),
    ("Scanner", "skip", "caturra's Scanner reads whole tokens and cannot skip by pattern"),
    ("Scanner", "tokens", "caturra's Scanner does not expose its tokens as a stream"),
    ("Scanner", "findAll", "caturra's Scanner does not expose matches as a stream"),
    ("Scanner", "nextBigInteger", "BigInteger is not supported by caturra"),
    ("Scanner", "nextBigDecimal", "BigDecimal is not supported by caturra"),
    // A `Spliterator` is a parallel-decomposition handle. caturra runs on one
    // thread and models no such type, so there is nothing honest to answer —
    // and "cannot find symbol" would read as a bug for a method the
    // documentation shows on every collection.
    ("ArrayList", "spliterator", "caturra does not model java.util.Spliterator"),
    ("Set", "spliterator", "caturra does not model java.util.Spliterator"),
    ("TreeSet", "spliterator", "caturra does not model java.util.Spliterator"),
    ("SortedSet", "spliterator", "caturra does not model java.util.Spliterator"),
    ("NavigableSet", "spliterator", "caturra does not model java.util.Spliterator"),
    ("Collection", "spliterator", "caturra does not model java.util.Spliterator"),
    ("LinkedList", "spliterator", "caturra does not model java.util.Spliterator"),
    ("HashMap", "of", "the immutable factories live on Map, not HashMap - write Map.of(...)"),
    ("HashMap", "ofEntries", "the immutable factories live on Map, not HashMap - write Map.ofEntries(...)"),
];

/// The source-level class name of a receiver that [`UNSUPPORTED_MEMBERS`]
/// has entries for. Empty for every other receiver, so that (say) a `File`
/// method never matches a `String` entry of the same name.
fn receiver_class_name(receiver: JType) -> &'static str {
    match receiver {
        JType::Str => "String",
        JType::Scanner => "Scanner",
        JType::List { .. } => "ArrayList",
        JType::Map { .. } => "HashMap",
        JType::TreeMap { role, .. } => role.map_internal().rsplit('/').next().unwrap_or("TreeMap"),
        JType::Set { .. } | JType::EntrySet { .. } => "Set",
        JType::TreeSet(_, role) => role.set_internal().rsplit('/').next().unwrap_or("TreeSet"),
        JType::LinkedList { .. } => "LinkedList",
        JType::Collection(_) => "Collection",
        JType::MapEntry { .. } => "Map.Entry",
        JType::StringBuilder => "StringBuilder",
        JType::Class => "Class",
        JType::Exception(_) => "Throwable",
        JType::Optional(_) => "Optional",
        JType::Stream(_) => "Stream",
        JType::File => "File",
        _ => "",
    }
}

/// The honest not-supported reason for a class member, if known.
fn unsupported_member(class: &str, method: &str) -> Option<&'static str> {
    UNSUPPORTED_MEMBERS
        .iter()
        .find(|(c, m, _)| *c == class && *m == method)
        .map(|(_, _, reason)| *reason)
}

