const OPTIONAL_METHODS: &[BuiltinMethod] = &[
    bm("getClass", &[], BRet::Class, "()Ljava/lang/Class;"),
    bm("isPresent", &[], BRet::Boolean, "()Z"),
    bm("isEmpty", &[], BRet::Boolean, "()Z"),
    bm("get", &[], BRet::Elem, "()Ljava/lang/Object;"),
    bm("orElseThrow", &[], BRet::Elem, "()Ljava/lang/Object;"),
    // `BParam::Elem`, not `Key`: an Optional stores its value UNBOXED (like a
    // list element), and `orElse` returns `BRet::Elem` — the unboxed element.
    // A boxed fallback (`Key`) made the two arms of `orElse` disagree: a
    // present `Optional<Integer>` yielded an `Int`, an empty one the boxed
    // fallback reference, and `println(opt.orElse(-1))` — dispatched `(I)V` by
    // the compile-time type — died on the reference at runtime.
    bm(
        "orElse",
        &[BParam::Elem],
        BRet::Elem,
        "(Ljava/lang/Object;)Ljava/lang/Object;",
    ),
    bm(
        "ifPresent",
        &[BParam::Consumer],
        BRet::Void,
        "(Ljava/util/function/Consumer;)V",
    ),
    // `filter(predicate)` keeps a present value only if it matches, so the
    // result is an `Optional` of the same element type.
    bm(
        "filter",
        &[BParam::Predicate],
        BRet::Optional,
        "(Ljava/util/function/Predicate;)Ljava/util/Optional;",
    ),
    // `map(function)` transforms a present value; its result element is erased
    // (like a stream's `map`), so the `Optional`'s element becomes `Object`.
    bm(
        "map",
        &[BParam::UnaryOperator],
        BRet::OptionalErased,
        "(Ljava/util/function/Function;)Ljava/util/Optional;",
    ),
    // `flatMap(function)` is `map` whose function already returns an Optional,
    // so the result is that Optional rather than one wrapped around it. Its
    // element is erased for the same reason `map`'s is.
    bm(
        "flatMap",
        &[BParam::UnaryOperator],
        BRet::OptionalErased,
        "(Ljava/util/function/Function;)Ljava/util/Optional;",
    ),
    // `orElseGet(supplier)` yields the value or the supplier's result — both the
    // element type.
    bm(
        "orElseGet",
        &[BParam::Supplier],
        BRet::Elem,
        "(Ljava/util/function/Supplier;)Ljava/lang/Object;",
    ),
    bm("toString", &[], BRet::Str, "()Ljava/lang/String;"),
];

